//! # dw-queue — the loop's engine
//!
//! The SQLite-backed pipeline store: jobs, results, adjudication ledger.
//! Port of `harness/pipeline/store.py`, sharing the same db file with the
//! Python dispatcher/loop — the two engines can operate one queue.
//!
//! The semantics being the SQL itself (the claim `UPDATE ... WHERE` with its
//! `rowcount` guard is the bounded-claim rule), the port keeps the statements
//! verbatim and proves it against the live reference with a scenario battery
//! (`tests/fixtures/gold/queue_battery_v1.json`, generated by
//! `scripts/gold_queue_battery.py`): enqueue/claim/ack id-FIFO, visibility
//! reclaim of crash leases, ack dedup on `(corpus_key, kind_hint,
//! extractor_version)`, fail → dead at `max_attempts`, budget caps.
//!
//! This crate calls no models and is `forbid(unsafe_code)`.

#![forbid(unsafe_code)]
#![deny(missing_docs)]

use std::cell::Cell;
use std::collections::BTreeMap;
use std::path::Path;

use rusqlite::{params, Connection, OptionalExtension};
use serde::{Deserialize, Serialize};

/// The schema, verbatim from the reference so both engines share one file.
const SCHEMA: &str = r"
CREATE TABLE IF NOT EXISTS jobs (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    kind TEXT NOT NULL,
    pillar TEXT,
    grain TEXT,
    schema_name TEXT,
    corpus_key TEXT NOT NULL,
    source_path TEXT,
    budget_tier TEXT,
    payload TEXT,
    state TEXT NOT NULL DEFAULT 'pending',
    claimed_by TEXT,
    claimed_at REAL,
    visibility_s REAL DEFAULT 3600,
    attempts INTEGER DEFAULT 0,
    max_attempts INTEGER DEFAULT 3,
    created_at REAL NOT NULL,
    updated_at REAL NOT NULL
);
CREATE INDEX IF NOT EXISTS idx_jobs_state ON jobs(state, kind);
CREATE INDEX IF NOT EXISTS idx_jobs_corpus ON jobs(corpus_key, kind);

CREATE TABLE IF NOT EXISTS results (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    job_id INTEGER NOT NULL REFERENCES jobs(id),
    extractor TEXT NOT NULL,
    extractor_version TEXT NOT NULL,
    corpus_key TEXT NOT NULL,
    document_sha256 TEXT,
    page_label_map TEXT,
    kind_hint TEXT NOT NULL DEFAULT 'substrate',
    output TEXT NOT NULL,
    created_at REAL NOT NULL,
    UNIQUE (corpus_key, kind_hint, extractor_version)
);
CREATE INDEX IF NOT EXISTS idx_results_corpus ON results(corpus_key);

CREATE TABLE IF NOT EXISTS adjudication_ledger (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    result_id INTEGER REFERENCES results(id),
    judge TEXT NOT NULL,
    judge_version TEXT,
    claim_index INTEGER,
    severity TEXT NOT NULL,
    verdict TEXT NOT NULL,
    reason_code TEXT,
    evidence_quote TEXT,
    extractor TEXT,
    failure_class TEXT,
    created_at REAL NOT NULL
);
CREATE INDEX IF NOT EXISTS idx_ledger_class ON adjudication_ledger(failure_class, created_at);

CREATE TABLE IF NOT EXISTS budget_spend (
    day TEXT NOT NULL,
    tier TEXT NOT NULL,
    jobs INTEGER DEFAULT 0,
    PRIMARY KEY (day, tier)
);
";

/// The clock the store stamps rows with. Injectable so the reference
/// battery replays byte-for-byte; production uses [`Clock::System`].
pub trait Clock {
    /// Seconds since the epoch, as the reference's `time.time()`.
    fn now(&self) -> f64;
    /// The day stamp (`%Y-%m-%d`) the budget table keys on.
    fn today(&self) -> String {
        // Day bucket of `now()`; [`Clock::System`] and [`ManualClock`]
        // override it. The gold masks this field — the reference keys the
        // budget on wall-clock `time.strftime`, which no outside clock can
        // pin (see `tests/queue_gold.rs`).
        format!("day+{}", (self.now() / 86_400.0).floor())
    }
}

/// The system clock.
#[derive(Debug, Clone, Copy, Default)]
pub struct SystemClock;

impl Clock for SystemClock {
    fn now(&self) -> f64 {
        std::time::SystemTime::now()
            .duration_since(std::time::UNIX_EPOCH)
            .map_or(0.0, |d| d.as_secs_f64())
    }
    fn today(&self) -> String {
        // UTC day bucket — the reference uses the local date; the budget
        // day is a coarse key and the gold test masks it (see tests/queue_gold.rs).
        format!("day+{}", (self.now() / 86_400.0).floor())
    }
}

/// A hand-cranked clock for tests and gold replays.
#[derive(Debug)]
pub struct ManualClock {
    t: Cell<f64>,
    day: String,
}

impl ManualClock {
    /// A clock starting at `t` with a fixed budget `day`.
    #[must_use]
    pub fn new(t: f64, day: &str) -> Self {
        Self {
            t: Cell::new(t),
            day: day.to_string(),
        }
    }
    /// Advance the clock.
    pub fn advance(&self, secs: f64) {
        self.t.set(self.t.get() + secs);
    }
}

impl Clock for ManualClock {
    fn now(&self) -> f64 {
        self.t.get()
    }
    fn today(&self) -> String {
        self.day.clone()
    }
}

/// One row of `jobs` — the wire shape is the reference's row, field for field.
#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
pub struct JobRow {
    /// Auto-increment id (FIFO order is by id).
    pub id: i64,
    /// `substrate | extract | adjudicate`.
    pub kind: String,
    /// Pillar, when the job names one.
    pub pillar: Option<String>,
    /// Grain, when the job names one.
    pub grain: Option<String>,
    /// Schema name, when the job names one.
    pub schema_name: Option<String>,
    /// `sha256:<hash>` for doc-grain, `node:<id>`, `query:<…>`.
    pub corpus_key: String,
    /// Source path, when the job names one.
    pub source_path: Option<String>,
    /// Budget tier, when the job names one.
    pub budget_tier: Option<String>,
    /// Opaque payload, JSON-encoded when present.
    pub payload: Option<String>,
    /// `pending|claimed|done|failed|dead`.
    pub state: String,
    /// Who holds the lease.
    pub claimed_by: Option<String>,
    /// Lease timestamp.
    pub claimed_at: Option<f64>,
    /// Lease visibility window (seconds).
    pub visibility_s: f64,
    /// Claim attempts so far.
    pub attempts: i64,
    /// Attempts before the job dies.
    pub max_attempts: i64,
    /// Created.
    pub created_at: f64,
    /// Updated.
    pub updated_at: f64,
}

/// What `enqueue` carries.
#[derive(Debug, Clone, Default)]
pub struct NewJob {
    /// `substrate | extract | adjudicate`.
    pub kind: String,
    /// Pillar.
    pub pillar: Option<String>,
    /// Grain.
    pub grain: Option<String>,
    /// Schema name.
    pub schema_name: Option<String>,
    /// Corpus key.
    pub corpus_key: String,
    /// Source path.
    pub source_path: Option<String>,
    /// Budget tier.
    pub budget_tier: Option<String>,
    /// Opaque payload (JSON-encoded on the wire).
    pub payload: Option<serde_json::Value>,
    /// Attempts before death.
    pub max_attempts: i64,
}

/// What `budget_check` reports.
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
pub struct BudgetState {
    /// Which day was charged.
    pub day: String,
    /// Which tier.
    pub tier: String,
    /// Jobs used after this call.
    pub used: i64,
    /// The cap.
    pub cap: i64,
}

/// One ledger verdict to record.
#[derive(Debug, Clone, Default)]
pub struct VerdictInput {
    /// Claim index.
    pub claim_index: Option<i64>,
    /// `P0|P1|P2|P3|P4`.
    pub severity: String,
    /// `SUPPORTED|UNSUPPORTED|NOT_IN_DOC|AMBIGUOUS`.
    pub verdict: String,
    /// Reason code.
    pub reason_code: Option<String>,
    /// Evidence quote.
    pub evidence_quote: Option<String>,
    /// Failure class.
    pub failure_class: Option<String>,
}

/// The store. Thin on purpose: the SQL is the semantics.
pub struct Queue {
    con: Connection,
    clock: Box<dyn Clock>,
}

impl Queue {
    /// Open (or create) the database at `path`, WAL mode, shared with the
    /// Python loop.
    ///
    /// # Errors
    ///
    /// Returns an error if the file cannot be opened or the schema cannot
    /// be applied.
    pub fn open(path: impl AsRef<Path>) -> Result<Self, rusqlite::Error> {
        Self::open_with_clock(path, SystemClock)
    }

    /// Open with an explicit clock (gold replays, tests).
    ///
    /// # Errors
    ///
    /// As [`Queue::open`].
    pub fn open_with_clock(
        path: impl AsRef<Path>,
        clock: impl Clock + 'static,
    ) -> Result<Self, rusqlite::Error> {
        if let Some(parent) = path.as_ref().parent() {
            let _ = std::fs::create_dir_all(parent);
        }
        let con = Connection::open(path)?;
        con.pragma_update(None, "journal_mode", "WAL")?;
        con.pragma_update(None, "busy_timeout", 30000)?;
        con.execute_batch(SCHEMA)?;
        Ok(Self {
            con,
            clock: Box::new(clock),
        })
    }

    /// The clock this store stamps with.
    #[must_use]
    pub fn now(&self) -> f64 {
        self.clock.now()
    }

    /// Enqueue one job; returns its id.
    ///
    /// # Errors
    ///
    /// As [`rusqlite::Error`].
    pub fn enqueue(&self, job: &NewJob) -> Result<i64, rusqlite::Error> {
        let payload = job
            .payload
            .as_ref()
            .map(serde_json::to_string)
            .transpose()
            .map_err(|e| rusqlite::Error::ToSqlConversionFailure(Box::new(e)))?;
        let ts = self.clock.now();
        self.con.execute(
            "INSERT INTO jobs (kind, pillar, grain, schema_name, corpus_key, source_path,
             budget_tier, payload, max_attempts, created_at, updated_at)
             VALUES (?,?,?,?,?,?,?,?,?,?,?)",
            params![
                job.kind,
                job.pillar,
                job.grain,
                job.schema_name,
                job.corpus_key,
                job.source_path,
                job.budget_tier,
                payload,
                job.max_attempts,
                ts,
                ts
            ],
        )?;
        Ok(self.con.last_insert_rowid())
    }

    /// Claim up to `limit` jobs of the given kinds — the reference's
    /// bounded claim: one `UPDATE … WHERE` per row, so two workers cannot
    /// take the same lease; id order is the FIFO.
    ///
    /// # Errors
    ///
    /// As [`rusqlite::Error`].
    pub fn claim(
        &self,
        worker: &str,
        kinds: &[&str],
        limit: usize,
    ) -> Result<Vec<JobRow>, rusqlite::Error> {
        let now = self.clock.now();
        let mut sql =
            String::from("SELECT * FROM jobs WHERE state IN ('pending','claimed') AND kind IN (");
        sql.push_str(&vec!["?"; kinds.len()].join(","));
        sql.push_str(
            ") AND (state='pending' OR claimed_at + visibility_s < ?)
             ORDER BY created_at DESC LIMIT ?",
        );
        let rows: Vec<JobRow> = {
            let mut stmt = self.con.prepare(&sql)?;
            let mut bind: Vec<&dyn rusqlite::ToSql> =
                kinds.iter().map(|k| k as &dyn rusqlite::ToSql).collect();
            bind.push(&now as &dyn rusqlite::ToSql);
            let lim = i64::try_from(limit).unwrap_or(i64::MAX);
            bind.push(&lim as &dyn rusqlite::ToSql);
            let rows = stmt
                .query_map(bind.as_slice(), row_to_job)?
                .collect::<Result<Vec<_>, _>>()?;
            rows
        };
        let mut claimed = Vec::new();
        for row in rows {
            let n = self.con.execute(
                "UPDATE jobs SET state='claimed', claimed_by=?, claimed_at=?,
                 attempts=attempts+1, updated_at=? WHERE id=?
                 AND (state='pending' OR claimed_at + visibility_s < ?)",
                params![worker, now, now, row.id, now],
            )?;
            if n > 0 {
                claimed.push(row);
            }
        }
        Ok(claimed)
    }

    /// Ack a job with its result; the unique key dedups repeated acks.
    /// Returns the result row id (`0` when the ack was ignored).
    ///
    /// # Errors
    ///
    /// As [`rusqlite::Error`].
    #[allow(clippy::too_many_arguments, reason = "mirrors the reference signature")]
    pub fn ack(
        &self,
        job_id: i64,
        extractor: &str,
        extractor_version: &str,
        output: &str,
        document_sha256: Option<&str>,
        page_label_map: Option<&serde_json::Value>,
        kind_hint: &str,
    ) -> Result<i64, rusqlite::Error> {
        let ts = self.clock.now();
        let corpus: String = self
            .con
            .query_row(
                "SELECT corpus_key FROM jobs WHERE id=?",
                params![job_id],
                |r| r.get(0),
            )
            .unwrap_or_else(|_| "?".to_string());
        let page_map = page_label_map
            .map(serde_json::to_string)
            .transpose()
            .map_err(|e| rusqlite::Error::ToSqlConversionFailure(Box::new(e)))?;
        self.con.execute(
            "INSERT OR IGNORE INTO results (job_id, extractor, extractor_version, corpus_key,
             document_sha256, page_label_map, output, kind_hint, created_at)
             VALUES (?,?,?,?,?,?,?,?,?)",
            params![
                job_id,
                extractor,
                extractor_version,
                corpus,
                document_sha256,
                page_map,
                output,
                kind_hint,
                ts
            ],
        )?;
        self.con.execute(
            "UPDATE jobs SET state='done', updated_at=? WHERE id=?",
            params![ts, job_id],
        )?;
        Ok(self.con.last_insert_rowid())
    }

    /// Fail a job: back to `pending`, or `dead` at `max_attempts`. Every
    /// failure leaves one ledger row — the queue's own adjudication trail.
    ///
    /// # Errors
    ///
    /// As [`rusqlite::Error`].
    pub fn fail(&self, job_id: i64, reason: &str) -> Result<(), rusqlite::Error> {
        let row = self
            .con
            .query_row(
                "SELECT attempts, max_attempts FROM jobs WHERE id=?",
                params![job_id],
                |r| Ok((r.get::<_, i64>(0)?, r.get::<_, i64>(1)?)),
            )
            .optional()?;
        let Some((attempts, max_attempts)) = row else {
            return Ok(());
        };
        let now = self.clock.now();
        let state = if attempts >= max_attempts {
            "dead"
        } else {
            "pending"
        };
        self.con.execute(
            "UPDATE jobs SET state=?, updated_at=? WHERE id=?",
            params![state, now, job_id],
        )?;
        self.con.execute(
            "INSERT INTO adjudication_ledger (judge, severity, verdict, reason_code, created_at)
             VALUES (?, ?, ?, ?, ?)",
            params![
                "queue",
                "P3",
                "JOB_FAILED",
                reason.chars().take(200).collect::<String>(),
                now
            ],
        )?;
        Ok(())
    }

    /// Charge one job against the tier's daily cap.
    ///
    /// # Errors
    ///
    /// As [`rusqlite::Error`].
    pub fn budget_check(
        &self,
        tier: &str,
        caps: &BTreeMap<String, i64>,
    ) -> Result<(bool, BudgetState), rusqlite::Error> {
        let day = self.clock.today();
        let used: i64 = self
            .con
            .query_row(
                "SELECT jobs FROM budget_spend WHERE day=? AND tier=?",
                params![day, tier],
                |r| r.get(0),
            )
            .optional()?
            .unwrap_or(0);
        let cap = caps.get(tier).copied().unwrap_or(0);
        if used >= cap {
            return Ok((
                false,
                BudgetState {
                    day,
                    tier: tier.into(),
                    used,
                    cap,
                },
            ));
        }
        self.con.execute(
            "INSERT INTO budget_spend (day, tier, jobs) VALUES (?,?,1)
             ON CONFLICT(day, tier) DO UPDATE SET jobs = jobs + 1",
            params![day, tier],
        )?;
        Ok((
            true,
            BudgetState {
                day,
                tier: tier.into(),
                used: used + 1,
                cap,
            },
        ))
    }

    /// Record adjudication verdicts against a result.
    ///
    /// # Errors
    ///
    /// As [`rusqlite::Error`].
    pub fn record_verdicts(
        &self,
        result_id: i64,
        judge: &str,
        judge_version: &str,
        verdicts: &[VerdictInput],
        extractor: Option<&str>,
    ) -> Result<(), rusqlite::Error> {
        let ts = self.clock.now();
        for v in verdicts {
            self.con.execute(
                "INSERT INTO adjudication_ledger (result_id, judge, judge_version, claim_index,
                 severity, verdict, reason_code, evidence_quote, extractor, failure_class, created_at)
                 VALUES (?,?,?,?,?,?,?,?,?,?,?)",
                params![
                    result_id,
                    judge,
                    judge_version,
                    v.claim_index,
                    v.severity,
                    v.verdict,
                    v.reason_code,
                    v.evidence_quote,
                    extractor,
                    v.failure_class,
                    ts
                ],
            )?;
        }
        Ok(())
    }

    /// The ledger rollup: `(failure_class, severity, n)` since `since`.
    ///
    /// # Errors
    ///
    /// As [`rusqlite::Error`].
    pub fn ledger_summary(
        &self,
        since: f64,
    ) -> Result<Vec<(Option<String>, String, i64)>, rusqlite::Error> {
        let mut stmt = self.con.prepare(
            "SELECT failure_class, severity, COUNT(*) FROM adjudication_ledger
             WHERE created_at > ? GROUP BY failure_class, severity ORDER BY COUNT(*) DESC",
        )?;
        let rows = stmt
            .query_map(params![since], |r| Ok((r.get(0)?, r.get(1)?, r.get(2)?)))?
            .collect::<Result<Vec<_>, _>>()?;
        Ok(rows)
    }

    /// Dump the four tables in the gold battery's shape — the wire the
    /// parity tests compare.
    ///
    /// # Errors
    ///
    /// As [`rusqlite::Error`].
    pub fn dump_tables(&self) -> Result<serde_json::Value, rusqlite::Error> {
        fn rows(
            con: &Connection,
            table: &str,
            order: &str,
        ) -> Result<serde_json::Value, rusqlite::Error> {
            let mut stmt = con.prepare(&format!("SELECT * FROM {table} ORDER BY {order}"))?;
            let cols: Vec<String> = stmt
                .column_names()
                .iter()
                .map(ToString::to_string)
                .collect();
            let mut out = Vec::new();
            let mut rows = stmt.query([])?;
            while let Some(row) = rows.next()? {
                let mut obj = serde_json::Map::new();
                for (i, c) in cols.iter().enumerate() {
                    let v = match row.get_ref(i)? {
                        rusqlite::types::ValueRef::Null => serde_json::Value::Null,
                        rusqlite::types::ValueRef::Integer(n) => serde_json::Value::from(n),
                        rusqlite::types::ValueRef::Real(f) => serde_json::json!(f),
                        rusqlite::types::ValueRef::Text(t) => {
                            serde_json::Value::String(String::from_utf8_lossy(t).into_owned())
                        }
                        rusqlite::types::ValueRef::Blob(b) => {
                            serde_json::Value::String(format!("blob:{}", b.len()))
                        }
                    };
                    obj.insert(c.clone(), v);
                }
                out.push(serde_json::Value::Object(obj));
            }
            Ok(serde_json::Value::Array(out))
        }
        let mut map = serde_json::Map::new();
        map.insert("jobs".into(), rows(&self.con, "jobs", "id")?);
        map.insert("results".into(), rows(&self.con, "results", "id")?);
        map.insert(
            "adjudication_ledger".into(),
            rows(&self.con, "adjudication_ledger", "id")?,
        );
        map.insert(
            "budget_spend".into(),
            rows(&self.con, "budget_spend", "day, tier")?,
        );
        Ok(serde_json::Value::Object(map))
    }
}

fn row_to_job(r: &rusqlite::Row<'_>) -> Result<JobRow, rusqlite::Error> {
    Ok(JobRow {
        id: r.get(0)?,
        kind: r.get(1)?,
        pillar: r.get(2)?,
        grain: r.get(3)?,
        schema_name: r.get(4)?,
        corpus_key: r.get(5)?,
        source_path: r.get(6)?,
        budget_tier: r.get(7)?,
        payload: r.get(8)?,
        state: r.get(9)?,
        claimed_by: r.get(10)?,
        claimed_at: r.get(11)?,
        visibility_s: r.get(12)?,
        attempts: r.get(13)?,
        max_attempts: r.get(14)?,
        created_at: r.get(15)?,
        updated_at: r.get(16)?,
    })
}
